-- =====================================================================
-- Customer Shopping Behavior Analysis — Combined SQL Script
-- Database : customer_behaviour
-- Table    : customer
-- Dialect  : PostgreSQL
--
-- This file combines the foundational analysis and advanced analysis
-- scripts. Both sections query the existing `customer` table.
-- Check that the table and column names match your database before running.
-- =====================================================================

-- =====================================================================
-- PART 1: FOUNDATIONAL CUSTOMER BEHAVIOR ANALYSIS
-- =====================================================================

-- ---------------------------------------------------------------------\n-- 0. Sanity checks\n-- ---------------------------------------------------------------------\nSELECT COUNT(*) AS total_rows FROM customer;\n\nSELECT * FROM customer LIMIT 5;\n\n\n-- ---------------------------------------------------------------------\n-- 1. Total revenue and average purchase by gender\n--    Question: Do male and female customers differ in spending?\n-- ---------------------------------------------------------------------\nSELECT\n    gender,\n    COUNT(*)                          AS customers,\n    SUM(purchase_amount_usd)          AS total_revenue,\n    ROUND(AVG(purchase_amount_usd), 2) AS avg_purchase\nFROM customer\nGROUP BY gender\nORDER BY total_revenue DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 2. Revenue by product category\n-- ---------------------------------------------------------------------\nSELECT\n    category,\n    COUNT(*)                           AS orders,\n    SUM(purchase_amount_usd)           AS total_revenue,\n    ROUND(AVG(purchase_amount_usd), 2) AS avg_purchase\nFROM customer\nGROUP BY category\nORDER BY total_revenue DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 3. Customers who used a discount but still spent more than average\n-- ---------------------------------------------------------------------\nSELECT\n    customer_id,\n    purchase_amount_usd\nFROM customer\nWHERE discount_applied = 'Yes'\n  AND purchase_amount_usd >= (SELECT AVG(purchase_amount_usd) FROM customer)\nORDER BY purchase_amount_usd DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 4. Top 5 products by average review rating\n-- ---------------------------------------------------------------------\nSELECT\n    item_purchased,\n    ROUND(AVG(review_rating)::numeric, 2) AS avg_rating\nFROM customer\nGROUP BY item_purchased\nORDER BY avg_rating DESC\nLIMIT 5;\n\n\n-- ---------------------------------------------------------------------\n-- 5. Average purchase amount: Standard vs Express shipping\n-- ---------------------------------------------------------------------\nSELECT\n    shipping_type,\n    COUNT(*)                           AS orders,\n    ROUND(AVG(purchase_amount_usd), 2) AS avg_purchase\nFROM customer\nWHERE shipping_type IN ('Standard', 'Express')\nGROUP BY shipping_type;\n\n-- All shipping types, for the dashboard\nSELECT\n    shipping_type,\n    COUNT(*)                           AS orders,\n    ROUND(AVG(purchase_amount_usd), 2) AS avg_purchase\nFROM customer\nGROUP BY shipping_type\nORDER BY avg_purchase DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 6. Subscribers vs non-subscribers\n--    Question: Do subscribers spend more?\n-- ---------------------------------------------------------------------\nSELECT\n    subscription_status,\n    COUNT(customer_id)                 AS total_customers,\n    ROUND(AVG(purchase_amount_usd), 2) AS avg_spend,\n    SUM(purchase_amount_usd)           AS total_revenue\nFROM customer\nGROUP BY subscription_status\nORDER BY total_revenue DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 7. Top 5 products with the highest percentage of discounted purchases\n-- ---------------------------------------------------------------------\nSELECT\n    item_purchased,\n    ROUND(\n        100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),\n        2\n    ) AS discount_rate_pct\nFROM customer\nGROUP BY item_purchased\nORDER BY discount_rate_pct DESC\nLIMIT 5;\n\n\n-- ---------------------------------------------------------------------\n-- 8. Customer segments: New, Returning, Loyal\n--    (based on number of previous purchases)\n-- ---------------------------------------------------------------------\nWITH customer_type AS (\n    SELECT\n        customer_id,\n        previous_purchases,\n        CASE\n            WHEN previous_purchases = 1                THEN 'New'\n            WHEN previous_purchases BETWEEN 2 AND 10   THEN 'Returning'\n            ELSE 'Loyal'\n        END AS customer_segment\n    FROM customer\n)\nSELECT\n    customer_segment,\n    COUNT(*) AS number_of_customers\nFROM customer_type\nGROUP BY customer_segment\nORDER BY number_of_customers DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 9. Top 3 most purchased products within each category\n--    (window function: ROW_NUMBER with PARTITION BY)\n-- ---------------------------------------------------------------------\nWITH item_counts AS (\n    SELECT\n        category,\n        item_purchased,\n        COUNT(customer_id) AS total_orders,\n        ROW_NUMBER() OVER (\n            PARTITION BY category\n            ORDER BY COUNT(customer_id) DESC\n        ) AS item_rank\n    FROM customer\n    GROUP BY category, item_purchased\n)\nSELECT\n    item_rank,\n    category,\n    item_purchased,\n    total_orders\nFROM item_counts\nWHERE item_rank <= 3\nORDER BY category, item_rank;\n\n\n-- ---------------------------------------------------------------------\n-- 10. Are repeat buyers (more than 5 previous purchases) more likely\n--     to subscribe?\n-- ---------------------------------------------------------------------\nSELECT\n    subscription_status,\n    COUNT(customer_id) AS repeat_buyers\nFROM customer\nWHERE previous_purchases > 5\nGROUP BY subscription_status;\n\n\n-- ---------------------------------------------------------------------\n-- 11. Revenue contribution by age group\n--     Age groups match the pandas quartile split (about 18-31, 32-44,\n--     45-57, 58-70).\n-- ---------------------------------------------------------------------\nWITH grouped AS (\n    SELECT\n        CASE\n            WHEN age <= 31 THEN 'Young Adults'\n            WHEN age <= 44 THEN 'Adults'\n            WHEN age <= 57 THEN 'Middle Aged'\n            ELSE 'Senior'\n        END AS age_group,\n        purchase_amount_usd\n    FROM customer\n)\nSELECT\n    age_group,\n    COUNT(*)                           AS orders,\n    SUM(purchase_amount_usd)           AS total_revenue,\n    ROUND(AVG(purchase_amount_usd), 2) AS avg_purchase\nFROM grouped\nGROUP BY age_group\nORDER BY total_revenue DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 12. Purchase frequency: how many customers buy at each interval\n-- ---------------------------------------------------------------------\nSELECT\n    frequency_of_purchases,\n    COUNT(*) AS customers\nFROM customer\nGROUP BY frequency_of_purchases\nORDER BY customers DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 13. Revenue by payment method\n-- ---------------------------------------------------------------------\nSELECT\n    payment_method,\n    COUNT(*)                 AS orders,\n    SUM(purchase_amount_usd) AS total_revenue\nFROM customer\nGROUP BY payment_method\nORDER BY total_revenue DESC;\n\n\n-- =====================================================================\n-- PART 2: ADVANCED CUSTOMER BEHAVIOR ANALYSIS\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- 1. RFM-style customer segmentation\n--    There is no purchase date in this dataset, so:\n--      Recency   -> how often the customer buys (shorter gap = higher score)\n--      Frequency -> number of previous purchases\n--      Monetary  -> purchase amount\n--    Each is scored 1-4 with NTILE, then combined into a segment.\n-- ---------------------------------------------------------------------\nWITH base AS (\n    SELECT\n        customer_id,\n        previous_purchases,\n        purchase_amount_usd,\n        CASE frequency_of_purchases\n            WHEN 'Weekly'         THEN 7\n            WHEN 'Fortnightly'    THEN 14\n            WHEN 'Bi-Weekly'      THEN 14\n            WHEN 'Monthly'        THEN 30\n            WHEN 'Quarterly'      THEN 90\n            WHEN 'Every 3 Months' THEN 90\n            WHEN 'Annually'       THEN 365\n        END AS days_between_purchases\n    FROM customer\n),\nscored AS (\n    SELECT\n        customer_id,\n        previous_purchases,\n        purchase_amount_usd,\n        NTILE(4) OVER (ORDER BY days_between_purchases DESC) AS r_score,\n        NTILE(4) OVER (ORDER BY previous_purchases)          AS f_score,\n        NTILE(4) OVER (ORDER BY purchase_amount_usd)         AS m_score\n    FROM base\n),\ntotals AS (\n    SELECT *, r_score + f_score + m_score AS rfm_total\n    FROM scored\n),\nsegments AS (\n    SELECT\n        *,\n        CASE\n            WHEN rfm_total >= 10 THEN 'Champions'\n            WHEN rfm_total >= 8  THEN 'Loyal'\n            WHEN rfm_total >= 6  THEN 'Potential'\n            ELSE 'At Risk'\n        END AS segment\n    FROM totals\n)\nSELECT\n    segment,\n    COUNT(*)                                          AS customers,\n    ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS pct_of_customers,\n    ROUND(AVG(purchase_amount_usd), 2)                AS avg_purchase,\n    ROUND(AVG(previous_purchases), 1)                 AS avg_previous_purchases\nFROM segments\nGROUP BY segment\nORDER BY MIN(rfm_total) DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 2. Pareto analysis: which items make up most of the revenue?\n--    Running total with a window function.\n-- ---------------------------------------------------------------------\nWITH item_revenue AS (\n    SELECT\n        item_purchased,\n        SUM(purchase_amount_usd) AS revenue\n    FROM customer\n    GROUP BY item_purchased\n),\nrunning AS (\n    SELECT\n        item_purchased,\n        revenue,\n        SUM(revenue) OVER (\n            ORDER BY revenue DESC, item_purchased\n            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n        ) AS running_revenue,\n        SUM(revenue) OVER () AS total_revenue\n    FROM item_revenue\n)\nSELECT\n    item_purchased,\n    revenue,\n    ROUND(100.0 * revenue / total_revenue, 2)         AS pct_of_total,\n    ROUND(100.0 * running_revenue / total_revenue, 2) AS cumulative_pct\nFROM running\nORDER BY revenue DESC, item_purchased;\n\n\n-- ---------------------------------------------------------------------\n-- 3. Category revenue share, with each category's rank\n-- ---------------------------------------------------------------------\nSELECT\n    category,\n    SUM(purchase_amount_usd)                                       AS revenue,\n    ROUND(100.0 * SUM(purchase_amount_usd)\n          / SUM(SUM(purchase_amount_usd)) OVER (), 2)              AS pct_of_total,\n    RANK() OVER (ORDER BY SUM(purchase_amount_usd) DESC)           AS revenue_rank\nFROM customer\nGROUP BY category\nORDER BY revenue_rank;\n\n\n-- ---------------------------------------------------------------------\n-- 4. Top 3 spenders in each category, and how far above the category\n--    average they are\n-- ---------------------------------------------------------------------\nWITH ranked AS (\n    SELECT\n        customer_id,\n        category,\n        purchase_amount_usd,\n        ROW_NUMBER() OVER (\n            PARTITION BY category\n            ORDER BY purchase_amount_usd DESC, customer_id\n        ) AS spend_rank,\n        AVG(purchase_amount_usd) OVER (PARTITION BY category) AS category_avg\n    FROM customer\n)\nSELECT\n    category,\n    spend_rank,\n    customer_id,\n    purchase_amount_usd,\n    ROUND(category_avg, 2)                         AS category_avg,\n    ROUND(purchase_amount_usd - category_avg, 2)   AS above_avg_by\nFROM ranked\nWHERE spend_rank <= 3\nORDER BY category, spend_rank;\n\n\n-- ---------------------------------------------------------------------\n-- 5. Items rated above their own category average\n-- ---------------------------------------------------------------------\nWITH item_rating AS (\n    SELECT\n        category,\n        item_purchased,\n        AVG(review_rating) AS item_avg_rating,\n        COUNT(*)           AS orders\n    FROM customer\n    GROUP BY category, item_purchased\n),\ncategory_rating AS (\n    SELECT\n        category,\n        AVG(review_rating) AS category_avg_rating\n    FROM customer\n    GROUP BY category\n)\nSELECT\n    i.category,\n    i.item_purchased,\n    i.orders,\n    ROUND(i.item_avg_rating::numeric, 2)                          AS item_rating,\n    ROUND(c.category_avg_rating::numeric, 2)                      AS category_rating,\n    ROUND((i.item_avg_rating - c.category_avg_rating)::numeric, 2) AS difference\nFROM item_rating i\nJOIN category_rating c ON c.category = i.category\nWHERE i.item_avg_rating > c.category_avg_rating\nORDER BY difference DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 6. Does a discount change how much people spend? (by category)\n--    Conditional aggregation with FILTER.\n-- ---------------------------------------------------------------------\nWITH discount_compare AS (\n    SELECT\n        category,\n        AVG(purchase_amount_usd) FILTER (WHERE discount_applied = 'Yes') AS avg_with_discount,\n        AVG(purchase_amount_usd) FILTER (WHERE discount_applied = 'No')  AS avg_without_discount,\n        COUNT(*) FILTER (WHERE discount_applied = 'Yes')                 AS discounted_orders,\n        COUNT(*) FILTER (WHERE discount_applied = 'No')                  AS full_price_orders\n    FROM customer\n    GROUP BY category\n)\nSELECT\n    category,\n    ROUND(avg_with_discount, 2)                         AS avg_with_discount,\n    ROUND(avg_without_discount, 2)                      AS avg_without_discount,\n    ROUND(avg_with_discount - avg_without_discount, 2)  AS difference,\n    discounted_orders,\n    full_price_orders\nFROM discount_compare\nORDER BY difference DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 7. Subscriber spending uplift by age group\n-- ---------------------------------------------------------------------\nWITH aged AS (\n    SELECT\n        CASE\n            WHEN age <= 31 THEN 'Young Adults'\n            WHEN age <= 44 THEN 'Adults'\n            WHEN age <= 57 THEN 'Middle Aged'\n            ELSE 'Senior'\n        END AS age_group,\n        subscription_status,\n        purchase_amount_usd\n    FROM customer\n),\npivoted AS (\n    SELECT\n        age_group,\n        AVG(purchase_amount_usd) FILTER (WHERE subscription_status = 'Yes') AS subscriber_avg,\n        AVG(purchase_amount_usd) FILTER (WHERE subscription_status = 'No')  AS non_subscriber_avg,\n        COUNT(*) FILTER (WHERE subscription_status = 'Yes')                 AS subscribers,\n        COUNT(*)                                                             AS total_customers\n    FROM aged\n    GROUP BY age_group\n)\nSELECT\n    age_group,\n    ROUND(subscriber_avg, 2)                       AS subscriber_avg,\n    ROUND(non_subscriber_avg, 2)                   AS non_subscriber_avg,\n    ROUND(subscriber_avg - non_subscriber_avg, 2)  AS uplift,\n    ROUND(100.0 * subscribers / total_customers, 2) AS subscription_rate_pct\nFROM pivoted\nORDER BY uplift DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 8. Season-over-season revenue change per category (LAG)\n--    Seasons are ordered Spring -> Summer -> Fall -> Winter.\n-- ---------------------------------------------------------------------\nWITH season_revenue AS (\n    SELECT\n        category,\n        season,\n        CASE season\n            WHEN 'Spring' THEN 1\n            WHEN 'Summer' THEN 2\n            WHEN 'Fall'   THEN 3\n            WHEN 'Winter' THEN 4\n        END AS season_order,\n        SUM(purchase_amount_usd) AS revenue\n    FROM customer\n    GROUP BY category, season\n),\nwith_previous AS (\n    SELECT\n        category,\n        season,\n        season_order,\n        revenue,\n        LAG(revenue) OVER (PARTITION BY category ORDER BY season_order) AS previous_revenue\n    FROM season_revenue\n)\nSELECT\n    category,\n    season,\n    revenue,\n    previous_revenue,\n    ROUND(100.0 * (revenue - previous_revenue) / NULLIF(previous_revenue, 0), 2) AS pct_change\nFROM with_previous\nORDER BY category, season_order;\n\n\n-- ---------------------------------------------------------------------\n-- 9. Unusually high purchases (z-score within each category)\n--    Purchases range from $20 to $100, so a z-score above 1.5 is used\n--    (a threshold of 2 would return no rows on this dataset).\n-- ---------------------------------------------------------------------\nWITH category_stats AS (\n    SELECT\n        category,\n        AVG(purchase_amount_usd)    AS mean_amount,\n        STDDEV(purchase_amount_usd) AS std_amount\n    FROM customer\n    GROUP BY category\n)\nSELECT\n    c.customer_id,\n    c.category,\n    c.item_purchased,\n    c.purchase_amount_usd,\n    ROUND(s.mean_amount, 2) AS category_mean,\n    ROUND(((c.purchase_amount_usd - s.mean_amount) / s.std_amount)::numeric, 2) AS z_score\nFROM customer c\nJOIN category_stats s ON s.category = c.category\nWHERE (c.purchase_amount_usd - s.mean_amount) / s.std_amount > 1.5\nORDER BY z_score DESC\nLIMIT 20;\n\n\n-- ---------------------------------------------------------------------\n-- 10. Revenue concentration: how much do the top 10% of orders contribute?\n--     NTILE(10) splits orders into deciles by purchase amount.\n-- ---------------------------------------------------------------------\nWITH deciles AS (\n    SELECT\n        customer_id,\n        purchase_amount_usd,\n        NTILE(10) OVER (ORDER BY purchase_amount_usd DESC) AS decile\n    FROM customer\n)\nSELECT\n    decile,\n    COUNT(*)                                              AS orders,\n    MIN(purchase_amount_usd)                              AS min_amount,\n    MAX(purchase_amount_usd)                              AS max_amount,\n    SUM(purchase_amount_usd)                              AS revenue,\n    ROUND(100.0 * SUM(purchase_amount_usd)\n          / SUM(SUM(purchase_amount_usd)) OVER (), 2)     AS pct_of_revenue\nFROM deciles\nGROUP BY decile\nORDER BY decile;\n\n\n-- ---------------------------------------------------------------------\n-- 11. Mean vs median purchase by category\n--     A big gap between them would signal skewed spending.\n-- ---------------------------------------------------------------------\nSELECT\n    category,\n    ROUND(AVG(purchase_amount_usd), 2) AS mean_purchase,\n    ROUND(\n        (PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY purchase_amount_usd))::numeric,\n        2\n    )                                  AS median_purchase,\n    MIN(purchase_amount_usd)           AS min_purchase,\n    MAX(purchase_amount_usd)           AS max_purchase\nFROM customer\nGROUP BY category\nORDER BY mean_purchase DESC;\n\n\n-- ---------------------------------------------------------------------\n-- 12. Payment method preference within each age group\n--     Percentages add up to 100 inside each age group.\n-- ---------------------------------------------------------------------\nWITH aged AS (\n    SELECT\n        CASE\n            WHEN age <= 31 THEN 'Young Adults'\n            WHEN age <= 44 THEN 'Adults'\n            WHEN age <= 57 THEN 'Middle Aged'\n            ELSE 'Senior'\n        END AS age_group,\n        payment_method\n    FROM customer\n),\ncounts AS (\n    SELECT age_group, payment_method, COUNT(*) AS customers\n    FROM aged\n    GROUP BY age_group, payment_method\n)\nSELECT\n    age_group,\n    payment_method,\n    customers,\n    ROUND(100.0 * customers / SUM(customers) OVER (PARTITION BY age_group), 2) AS pct_within_age_group,\n    RANK() OVER (PARTITION BY age_group ORDER BY customers DESC)               AS preference_rank\nFROM counts\nORDER BY age_group, preference_rank;\n\n\n-- ---------------------------------------------------------------------\n-- 13. Locations with above-average revenue (top 10)\n-- ---------------------------------------------------------------------\nWITH location_stats AS (\n    SELECT\n        location,\n        COUNT(*)                 AS orders,\n        SUM(purchase_amount_usd) AS revenue\n    FROM customer\n    GROUP BY location\n),\nranked AS (\n    SELECT\n        *,\n        RANK() OVER (ORDER BY revenue DESC) AS revenue_rank,\n        AVG(revenue) OVER ()                AS avg_location_revenue\n    FROM location_stats\n)\nSELECT\n    revenue_rank,\n    location,\n    orders,\n    revenue,\n    ROUND(revenue - avg_location_revenue, 2) AS above_average_by\nFROM ranked\nWHERE revenue > avg_location_revenue\nORDER BY revenue_rank\nLIMIT 10;\n\n\n-- ---------------------------------------------------------------------\n-- 14. Subscription rate by loyalty level\n--     Are people who have bought more often more likely to subscribe?\n-- ---------------------------------------------------------------------\nWITH buckets AS (\n    SELECT\n        CASE\n            WHEN previous_purchases BETWEEN 1  AND 10 THEN '1-10'\n            WHEN previous_purchases BETWEEN 11 AND 25 THEN '11-25'\n            WHEN previous_purchases BETWEEN 26 AND 40 THEN '26-40'\n            ELSE '41-50'\n        END AS purchase_bucket,\n        subscription_status\n    FROM customer\n)\nSELECT\n    purchase_bucket,\n    COUNT(*)                                                         AS customers,\n    COUNT(*) FILTER (WHERE subscription_status = 'Yes')              AS subscribers,\n    ROUND(100.0 * COUNT(*) FILTER (WHERE subscription_status = 'Yes')\n          / COUNT(*), 2)                                             AS subscription_rate_pct\nFROM buckets\nGROUP BY purchase_bucket\nORDER BY MIN(\n    CASE purchase_bucket WHEN '1-10' THEN 1 WHEN '11-25' THEN 2 WHEN '26-40' THEN 3 ELSE 4 END\n);\n\n\n-- ---------------------------------------------------------------------\n-- 15. At-risk loyal customers\n--     Customers in the top quarter for previous purchases who gave a low\n--     rating (3.0 or below) and are not subscribed. These are good\n--     candidates for a retention offer.\n-- ---------------------------------------------------------------------\nWITH threshold AS (\n    SELECT\n        PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY previous_purchases) AS loyal_cutoff\n    FROM customer\n),\nat_risk AS (\n    SELECT\n        c.customer_id,\n        c.category,\n        c.item_purchased,\n        c.previous_purchases,\n        c.review_rating,\n        c.purchase_amount_usd\n    FROM customer c\n    CROSS JOIN threshold t\n    WHERE c.previous_purchases >= t.loyal_cutoff\n      AND c.review_rating <= 3.0\n      AND c.subscription_status = 'No'\n)\nSELECT\n    category,\n    COUNT(*)                           AS at_risk_customers,\n    ROUND(AVG(review_rating)::numeric, 2) AS avg_rating,\n    SUM(purchase_amount_usd)           AS revenue_at_risk\nFROM at_risk\nGROUP BY category\nORDER BY revenue_at_risk DESC;\n